#include <bits/stdc++.h>
using namespace std;

long long modPow(long long base, long long exp, long long mod) {
    long long res = 1;
    base %= mod;
    while (exp > 0) {
        if (exp & 1) {
            res = (res * base) % mod;
        }
        base = (base * base) % mod;
        exp >>= 1;
    }
    return res;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    long long n, m;
    cin >> n >> m;
    long long totalCells = n * m;
    long long l, r;
    cin >> l >> r;
    long long rangeLength = r - l + 1;
    const long long MOD = 998244353;

    if (totalCells % 2 == 1) {
        cout << modPow(rangeLength, totalCells, MOD) << "\n";
    } else {
        long long part1 = modPow(rangeLength, totalCells, MOD);
        long long part2 = modPow(rangeLength % 2, totalCells, MOD);
        long long invTwo = modPow(2, MOD - 2, MOD);
        long long result = ((part1 + part2) % MOD) * invTwo % MOD;
        cout << result << "\n";
    }
    return 0;
}

